+            ),
+            Some("lora_name"),
+        ),
+        LoadLoraError::BaseModelName { .. } => {
+            ApiError::invalid_request(message, Some("lora_name"))
+        }
+        LoadLoraError::Engine { .. } | LoadLoraError::NotLoaded { .. } => {
+            ApiError::server_error(message)
+        }
+    }
+}
